mapper.select:

/* Biz: gscm.r.pm.logb.db.DPLA035.S902 사용자 권한 체크 */
SELECT USER_ID
	 , MENU_ID
	 , AUTH_TYP_CD
  FROM COM_USER_AUTH
 WHERE USER_ID = #{USER_ID}
   AND MENU_ID = #{MENU_ID}
   AND AUTH_TYP_CD IN ('R','W')


/* Biz: gscm.r.pm.logb.db.DPLA035.S002 운송관리 상세 조회 */
SELECT B.TGT_CD
	 , B.DTL_SEQ
	 , B.WGT AS METRIC_VALUE
	 , B.METRIC_TYPE
  FROM LOI_DTL_05 B
 WHERE B.TGT_CD = #{TGT_CD}
   AND B.METRIC_TYPE = #{METRIC_TYPE}
